import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, Camara, Textura, Profundidad, Brillo, Paso, seguir, Recorrido, tono, Chip, Regla, Contador, Ondas, golpe, h, clamp, interpolate, Easing} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const BOST1 = en('bostezo'), BOST2 = en('bostezo', 2), BOST3 = en('bostezo', 3), BOST4 = en('bostezo', 4), BOSTECES = en('bosteces');
const PRESION = en('presión'), MAND = en('mandíbula'), HACE = en('hace'), VER = en('ver'), NADIE = en('nadie'), LEERLO = en('leerlo'), ESCUCH = en('escucharlo');
const ENTRE1 = en('Entre'), CUAR = en('cuarenta'), SES = en('sesenta'), CIEN = en('cien'), CONTAGIAN = en('contagian');
const PERO = en('Pero'), BEBES = en('bebés'), CUATRO = en('cuatro'), CINCO = en('cinco'), ANOS = en('años');
const JUSTO = en('Justo'), ENTENDER = en('entender'), DEMAS = en('demás');
const ITALIA = en('Italia'), ANOT = en('anotaron'), CIENTOS = en('cientos'), BOSTEZOS = en('bostezos'), VIDA = en('vida'), DIARIA = en('diaria');
const CONTAGIO2 = en('contagio', 2), FAMIL = en('familiares'), LUEGO = en('Luego'), AMIGOS = en('amigos'), DESC = en('desconocidos');
const POR = en('Por'), EMP = en('empatía'), CERCA = en('cerca'), ALGUIEN = en('alguien');
const HASTA = en('Hasta'), PERROS = en('perros'), BOSTEZAR2 = en('bostezar', 2), DUENO = en('dueño'), EXTRANO = en('extraño');
const ASI = en('Así'), SUENO = en('sueño'), IMPORTA = en('importa'), PALABRA2 = en('palabra', 2);
const DALE = en('Dale'), PERSONA = en('persona'), PEGA = en('pega');

const LIMA = '#E7FF00';
const abre = (s: number, a: number, b: number, c: number) => interpolate(s, [a, b, c], [0, 1, 0], {...clamp, easing: Easing.inOut(Easing.sin)});

const Mundo: React.FC<{children: React.ReactNode; w?: number}> = ({children, w = 3000}) => <svg width={w} height={1920} viewBox={`-600 0 ${w} 1920`} style={{position: 'absolute', left: -600, top: 0, overflow: 'visible'}}>{children}</svg>;

type Parada = {t: number; x: number; y: number; zoom: number};
// un lugar: textura detras, luz (Brillo) y el mundo dibujado dentro de la camara
const Lugar: React.FC<{tipo: 'piel' | 'celulas' | 'fibra' | 'papel'; base: string; linea: string; luz: string; semilla: number; bx: number; by: number; bc: string; paradas: Parada[]; w?: number; children: React.ReactNode}> = ({tipo, base, linea, luz, semilla, bx, by, bc, paradas, w, children}) => (
  <AbsoluteFill style={{background: '#1A1010'}}>
    <Textura tipo={tipo} base={base} linea={linea} luz={luz} semilla={semilla} />
    <Camara paradas={paradas}>
      <Brillo x={bx} y={by} r={720} color={bc} />
      <Mundo w={w}>{children}</Mundo>
    </Camara>
  </AbsoluteFill>
);

// ---------- piezas dibujadas ----------
// la nube-bostezo: protagonista lima con la boca abierta
const Nube: React.FC<{x: number; y: number; sc?: number; ang?: number; op?: number; boca?: number}> = ({x, y, sc = 1, ang = 0, op = 1, boca = 0.6}) => {
  const {s} = useS();
  const b = 1 + 0.05 * Math.sin(s * 5 + x * 0.01);
  const my = 10 + 38 * boca;
  return (
    <g transform={`translate(${x} ${y}) rotate(${ang}) scale(${sc * b})`} opacity={op}>
      <defs><radialGradient id="nbG" cx="38%" cy="28%" r="78%"><stop offset="0%" stopColor="#F8FFB0" /><stop offset="55%" stopColor="#E7FF00" /><stop offset="100%" stopColor="#97AA00" /></radialGradient></defs>
      <circle r={170} fill="rgba(231,255,0,0.16)" />
      {[[-66, 12, 62], [0, -34, 78], [68, 10, 60], [-22, 44, 68], [36, 48, 58]].map(([cx, cy, r], i) => <circle key={i} cx={cx} cy={cy} r={r} fill="url(#nbG)" />)}
      <ellipse cx={0} cy={26} rx={30} ry={my} fill="#5A1A22" />
      <ellipse cx={0} cy={26 + my * 0.55} rx={18} ry={6 + 12 * boca} fill="#E0607A" />
      {[-1, 1].map((k) => <path key={k} d={`M ${k * 36 - 13} -12 Q ${k * 36} -26 ${k * 36 + 13} -12`} stroke="#3A4A00" strokeWidth={7} fill="none" strokeLinecap="round" />)}
      <ellipse cx={-26} cy={-50} rx={26} ry={12} fill="rgba(255,255,255,0.45)" />
    </g>
  );
};

// cabeza simple con cara; boca 0..1 = bostezo
const Cara: React.FC<{x: number; y: number; sc?: number; boca?: number; piel?: string; pelo?: string; triste?: boolean; ojos?: number; op?: number; ang?: number; largo?: boolean}> = ({x, y, sc = 1, boca = 0, piel = '#F1C9A5', pelo = '#3A2418', triste = false, ojos = 1, op = 1, ang = 0, largo = false}) => {
  const cerrado = ojos < 0.3 || boca > 0.5;
  return (
    <g transform={`translate(${x} ${y}) rotate(${ang}) scale(${sc})`} opacity={op}>
      {largo && <path d="M -62 -10 C -80 60 -70 110 -50 130 L 50 130 C 70 110 80 60 62 -10 Z" fill={pelo} />}
      <circle r={60} fill={piel} stroke="rgba(90,50,30,0.5)" strokeWidth={3} />
      <path d="M -58 -8 C -64 -72 -20 -88 6 -82 C 46 -78 66 -50 58 -6 C 44 -40 14 -54 -14 -52 C -36 -50 -50 -34 -58 -8 Z" fill={pelo} />
      <ellipse cx={-38} cy={22} rx={13} ry={8} fill="rgba(235,110,110,0.35)" /><ellipse cx={38} cy={22} rx={13} ry={8} fill="rgba(235,110,110,0.35)" />
      {[-1, 1].map((k) => cerrado
        ? <path key={k} d={`M ${k * 22 - 9} -2 Q ${k * 22} ${boca > 0.5 ? -12 : 6} ${k * 22 + 9} -2`} stroke="#241410" strokeWidth={4.5} fill="none" strokeLinecap="round" />
        : <g key={k}><ellipse cx={k * 22} cy={-3} rx={6.5} ry={8 * ojos} fill="#241410" /><circle cx={k * 22 + 2} cy={-6} r={2.4} fill="#fff" /></g>)}
      {triste && [-1, 1].map((k) => <path key={'c' + k} d={`M ${k * 34} -14 L ${k * 12} -26`} stroke={pelo} strokeWidth={5} strokeLinecap="round" />)}
      {boca > 0.06
        ? <g><ellipse cx={0} cy={30} rx={11 + 12 * boca} ry={4 + 22 * boca} fill="#5A1A22" /><ellipse cx={0} cy={30 + 14 * boca} rx={9} ry={3 + 8 * boca} fill="#E0607A" /></g>
        : <path d={triste ? 'M -14 40 Q 0 28 14 40' : 'M -14 30 Q 0 40 14 30'} stroke="#7A3A2A" strokeWidth={4.5} fill="none" strokeLinecap="round" />}
    </g>
  );
};

// persona de cuerpo entero para la plaza
const Persona: React.FC<{x: number; y: number; sc?: number; col?: string; piel?: string; pelo?: string; dir?: number; boca?: number; camina?: number; libreta?: boolean; fase?: number}> = ({x, y, sc = 1, col = '#4A5A7A', piel = '#E3B08A', pelo = '#2A1E16', dir = 1, boca = 0, camina = 0, libreta = false, fase = 0}) => {
  const {s} = useS();
  const sw = Math.sin(s * 7 + fase) * 18 * camina;
  return (
    <g transform={`translate(${x} ${y}) scale(${dir * sc} ${sc})`}>
      <ellipse cx={0} cy={4} rx={66} ry={10} fill="rgba(0,0,0,0.22)" />
      <rect x={-24} y={-124} width={20} height={124} rx={10} fill="#2C2C3A" transform={`rotate(${sw} -14 -124)`} />
      <rect x={4} y={-124} width={20} height={124} rx={10} fill="#2C2C3A" transform={`rotate(${-sw} 14 -124)`} />
      <rect x={-38} y={-252} width={76} height={140} rx={30} fill={col} />
      <rect x={20} y={-242} width={17} height={104} rx={8} fill={col} transform={`rotate(${libreta ? -38 : -sw * 0.5} 28 -242)`} />
      {libreta && <g transform="translate(46 -176) rotate(-10)"><rect x={-4} y={-24} width={36} height={48} rx={4} fill="#FFF8EA" stroke="#B9A77E" strokeWidth={3} /><line x1={2} y1={-10} x2={24} y2={-10} stroke="#8A8A8A" strokeWidth={2} /><line x1={2} y1={2} x2={24} y2={2} stroke="#8A8A8A" strokeWidth={2} /></g>}
      <circle cx={0} cy={-294} r={36} fill={piel} stroke="rgba(90,50,30,0.4)" strokeWidth={3} />
      <path d="M -36 -296 Q -34 -334 0 -332 Q 36 -334 36 -296 Q 12 -318 -36 -296 Z" fill={pelo} />
      <circle cx={-12} cy={-296} r={3.5} fill="#241410" /><circle cx={12} cy={-296} r={3.5} fill="#241410" />
      {boca > 0.06 ? <ellipse cx={0} cy={-276} rx={8 + 6 * boca} ry={3 + 12 * boca} fill="#5A1A22" /> : <path d="M -8 -276 Q 0 -270 8 -276" stroke="#7A3A2A" strokeWidth={3} fill="none" />}
    </g>
  );
};

// ---------- E1 y E11-E12: la hoja con BOSTEZO sobre la mesa de la sala ----------
const Hoja: React.FC<{fin?: boolean}> = ({fin = false}) => {
  const {s, spr, lin} = useS();
  const T0 = fin ? ASI : 0;
  const o = fin ? spr(IMPORTA - 0.25, 9, 110) : spr(BOST1 - 0.05, 9, 110);
  const corazon = fin ? spr(IMPORTA + 0.1, 8, 150) : 0;
  const nubeK = fin ? lin(PERSONA, PEGA + 0.7, 0.2, 5.5, Easing.in(Easing.cubic)) : lin(BOSTECES - 0.2, BOSTECES + 1.6, 0, 1, Easing.out(Easing.cubic));
  const nubeY = fin ? 985 + 40 * lin(PERSONA, PEGA + 0.7, 0, 1) : 985 - 330 * nubeK;
  const nubeS = fin ? nubeK * lin(IMPORTA + 0.4, IMPORTA + 0.9, 0, 1) : 0.55 * nubeK;
  const bo = abre(s, BOST1 + 0.1, BOST1 + 0.9, BOST1 + 3.4);
  const abierta = fin ? Math.max(o * 0.9, 0) : Math.max(o * (0.4 + 0.6 * bo), 0);
  const x = (i: number) => 125 + i * 138;
  return (
    <Lugar tipo="fibra" base="radial-gradient(circle at 40% 28%, #F6D3A0 0%, #D9A065 50%, #6E4326 100%)" linea="rgba(100,55,25,0.45)" luz="rgba(255,236,190,0.35)" semilla={fin ? 3 : 2} bx={300} by={620} bc="rgba(255,226,160,0.6)"
      paradas={fin ? [{t: T0, x: 540, y: 1000, zoom: 1.0}, {t: IMPORTA + 0.2, x: 262, y: 985, zoom: 1.75}, {t: PEGA + 1.2, x: 262, y: 985, zoom: 1.5}] : [{t: 0, x: 540, y: 1010, zoom: 1.0}, {t: BOST1 + 0.3, x: 262, y: 985, zoom: 1.7}, {t: BOST2 + 0.4, x: 262, y: 985, zoom: 1.95}]}>
      <rect x={20} y={790} width={1040} height={420} rx={14} fill="#FFF7E6" stroke="#CDB48A" strokeWidth={6} transform="rotate(-2 540 1000)" />
      <g transform="rotate(-2 540 1000)">
        {[0, 1, 2].map((i) => <line key={i} x1={60} y1={1140 + i * 22} x2={1020} y2={1140 + i * 22} stroke="rgba(150,120,80,0.35)" strokeWidth={3} />)}
        {['B', 'O', 'S', 'T', 'E', 'Z', 'O'].map((c, i) => {
          if (c !== 'O') return <text key={i} x={x(i)} y={1070} textAnchor="middle" fontFamily="Poppins, Arial, sans-serif" fontWeight={900} fontSize={200} fill="#2A1A14">{c}</text>;
          return (
            <g key={i}>
              <ellipse cx={x(i)} cy={985} rx={64} ry={80 + 22 * abierta} fill="none" stroke="#2A1A14" strokeWidth={34} />
              <ellipse cx={x(i)} cy={985 + 6 * abierta} rx={34} ry={Math.max(4, 12 + 58 * abierta)} fill={abierta > 0.05 ? '#5A1A22' : 'none'} />
              {abierta > 0.2 && <ellipse cx={x(i)} cy={1010 + 14 * abierta} rx={22} ry={8 + 18 * abierta} fill="#E0607A" />}
              {i === 1 && corazon > 0.02 && <path transform={`translate(${x(i)} 975) scale(${corazon * 1.1})`} d="M 0 36 C -60 -6 -34 -50 0 -20 C 34 -50 60 -6 0 36 Z" fill={LIMA} stroke="#8A9A00" strokeWidth={4} />}
            </g>
          );
        })}
        <Nube x={x(1)} y={nubeY} sc={nubeS} boca={0.9} op={nubeS > 0.01 ? 1 : 0} />
      </g>
      {/* taza con vapor, luz de mañana */}
      <g transform="translate(930 560)">
        <ellipse cx={0} cy={92} rx={78} ry={14} fill="rgba(0,0,0,0.25)" />
        <path d="M -56 0 L 56 0 L 46 90 L -46 90 Z" fill="#F4E9D8" stroke="#B9A27A" strokeWidth={5} />
        <path d="M 56 20 C 100 20 100 70 52 66" stroke="#B9A27A" strokeWidth={9} fill="none" />
        {[0, 1, 2].map((i) => <path key={i} d={`M ${-20 + i * 20} -10 C ${-34 + i * 20 + Math.sin(s * 2 + i) * 14} -50 ${-6 + i * 20 + Math.cos(s * 2 + i) * 14} -80 ${-20 + i * 20} -120`} stroke="rgba(255,255,255,0.55)" strokeWidth={8} fill="none" strokeLinecap="round" />)}
      </g>
      {!fin && <Ondas x={262} y={985} t0={BOST1} color={LIMA} radio={300} />}
      {fin && <Ondas x={262} y={985} t0={IMPORTA} color="#FF8FB0" radio={340} />}
    </Lugar>
  );
};

// ---------- E2: la mandibula por dentro (lámina médica) ----------
const Mandibula: React.FC = () => {
  const {s, lin} = useS();
  const yaw = 26 * Math.max(abre(s, BOST2 + 0.2, BOST2 + 1.0, BOST2 + 2.2), abre(s, PRESION - 0.5, PRESION + 0.3, MAND + 1.4));
  const J = [640, 985];
  const rot = (px: number, py: number): [number, number] => {
    const a = (yaw * Math.PI) / 180, dx = px - J[0], dy = py - J[1];
    return [J[0] + dx * Math.cos(a) - dy * Math.sin(a), J[1] + dx * Math.sin(a) + dy * Math.cos(a)];
  };
  const glow = lin(MAND - 0.1, MAND + 0.4, 0, 1);
  const tops: [number, number][] = [[612, 914], [650, 910], [690, 908], [730, 910], [768, 914]];
  const bots = [[690, 1250], [722, 1252], [754, 1254], [786, 1252], [818, 1248]].map(([a, b]) => rot(a, b));
  const quad = `M ${tops[0][0]} ${tops[0][1]} L ${tops[4][0]} ${tops[4][1]} L ${bots[4][0]} ${bots[4][1]} L ${bots[0][0]} ${bots[0][1]} Z`;
  return (
    <Lugar tipo="celulas" base="radial-gradient(circle at 55% 42%, #8A3340 0%, #4A1A26 55%, #1E0A12 100%)" linea="rgba(255,150,150,0.25)" luz="rgba(255,120,120,0.10)" semilla={4} bx={700} by={980} bc="rgba(255,140,120,0.45)"
      paradas={[{t: BOST2 - 0.2, x: 640, y: 1040, zoom: 1.0}, {t: PRESION, x: 650, y: 1030, zoom: 1.45}, {t: MAND + 0.7, x: 650, y: 990, zoom: 2.1}]}>
      <defs>
        <linearGradient id="hueso" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#FBF1DA" /><stop offset="100%" stopColor="#C9B58C" /></linearGradient>
        <linearGradient id="musc" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#E2625A" /><stop offset="100%" stopColor="#A82A2E" /></linearGradient>
      </defs>
      <path d="M 330 990 C 290 700 450 520 640 520 C 820 520 900 680 890 860 C 888 930 870 975 840 992 L 640 992 C 520 992 420 1012 330 990 Z" fill="url(#hueso)" stroke="#8A7550" strokeWidth={5} />
      <path d="M 700 994 L 935 1002 L 935 1046 L 700 1046 Z" fill="url(#hueso)" stroke="#8A7550" strokeWidth={4} />
      {Array.from({length: 8}).map((_, i) => <rect key={i} x={706 + i * 29} y={1040} width={25} height={52} rx={9} fill="#fff" stroke="#BFB197" strokeWidth={3} />)}
      <ellipse cx={780} cy={800} rx={74} ry={58} fill="#3A1E22" stroke="#8A7550" strokeWidth={5} />
      <path d="M 888 880 L 936 930 L 880 940 Z" fill="#3A1E22" />
      <path d="M 560 920 C 640 880 740 880 800 900" stroke="#EADFC3" strokeWidth={34} fill="none" strokeLinecap="round" />
      <ellipse cx={596} cy={906} rx={16} ry={20} fill="#3A1E22" />
      <g transform={`rotate(${yaw} ${J[0]} ${J[1]})`}>
        <path d="M 610 958 C 640 948 690 958 700 990 L 704 1100 L 915 1100 C 940 1100 962 1118 952 1170 C 936 1232 880 1252 800 1252 L 650 1252 C 610 1252 584 1222 590 1180 Z" fill="url(#hueso)" stroke="#8A7550" strokeWidth={5} />
        {Array.from({length: 8}).map((_, i) => <rect key={i} x={706 + i * 28} y={1052} width={25} height={52} rx={9} fill="#fff" stroke="#BFB197" strokeWidth={3} />)}
        <circle cx={J[0]} cy={J[1]} r={30} fill="#D9C79F" stroke="#8A7550" strokeWidth={4} />
      </g>
      <path d={quad} fill="url(#musc)" opacity={0.9} />
      {tops.map((p, i) => <path key={i} d={`M ${p[0]} ${p[1]} Q ${(p[0] + bots[i][0]) / 2 + 12 * Math.sin(i + s * 3)} ${(p[1] + bots[i][1]) / 2} ${bots[i][0]} ${bots[i][1]}`} stroke="rgba(255,190,170,0.6)" strokeWidth={6} fill="none" strokeLinecap="round" />)}
      <path d={quad} fill="none" stroke={LIMA} strokeWidth={10} opacity={glow * (0.7 + 0.3 * Math.sin(s * 8))} strokeLinejoin="round" />
      <Ondas x={J[0]} y={J[1]} t0={MAND} color={LIMA} radio={300} />
    </Lugar>
  );
};

// ---------- E3: la nube sale de un parlante y de una hoja hacia una oreja y un ojo ----------
const Ojo: React.FC<{x: number; y: number; cierra?: number}> = ({x, y, cierra = 0}) => (
  <g transform={`translate(${x} ${y})`}>
    <path d="M -110 0 C -60 -86 60 -86 110 0 C 60 86 -60 86 -110 0 Z" fill="#FFF8F0" stroke="#7A5A48" strokeWidth={6} />
    <circle cx={0} cy={0} r={52} fill="#4A8A5A" stroke="#2A4A32" strokeWidth={4} />
    <circle cx={0} cy={0} r={22} fill="#101010" /><circle cx={-12} cy={-14} r={9} fill="#fff" />
    <path d={`M -112 0 C -60 ${-90 + 80 * cierra} 60 ${-90 + 80 * cierra} 112 0 L 112 -2 C 60 -100 -60 -100 -112 -2 Z`} fill="#D9A27A" stroke="#7A5A48" strokeWidth={5} opacity={cierra > 0.02 ? 1 : 0} />
  </g>
);
const Parlante: React.FC = () => {
  const {s, lin} = useS();
  const rutaOjo: [number, number][] = [[250, 1330], [520, 1250], [790, 1320]];
  const rutaOido: [number, number][] = [[250, 790], [520, 700], [790, 770]];
  const pop = (t: number) => lin(t, t + 0.35, 0, 1, Easing.out(Easing.back(1.8)));
  const vibra = 1 + 0.06 * Math.sin(s * 30) * (s > ESCUCH - 0.2 && s < ESCUCH + 0.7 ? 1 : 0);
  return (
    <Lugar tipo="papel" base="linear-gradient(180deg, #F7DDB0 0%, #E8B97C 55%, #B67A47 100%)" linea="rgba(120,70,30,0.25)" luz="rgba(255,240,200,0.3)" semilla={5} bx={540} by={900} bc="rgba(255,230,170,0.55)"
      paradas={[{t: HACE - 0.2, x: 540, y: 1030, zoom: 1.0}, {t: LEERLO - 0.4, x: 520, y: 1290, zoom: 1.25}, {t: LEERLO + 0.9, x: 700, y: 1300, zoom: 1.5}, {t: ESCUCH + 0.1, x: 520, y: 760, zoom: 1.25}, {t: ESCUCH + 1.1, x: 700, y: 770, zoom: 1.5}]}>
      {/* hoja y ojo (leer) */}
      <g transform={`translate(250 1330) scale(${pop(HACE)})`}>
        <rect x={-110} y={-130} width={220} height={260} rx={12} fill="#FFF8EA" stroke="#CDB48A" strokeWidth={5} transform="rotate(-4)" />
        <text x={0} y={10} textAnchor="middle" fontFamily="Poppins, Arial, sans-serif" fontWeight={900} fontSize={42} fill="#2A1A14" transform="rotate(-4)">BOSTEZO</text>
      </g>
      <g transform={`scale(${pop(VER)})`} style={{transformOrigin: '790px 1320px'}}><Ojo x={790} y={1320} cierra={abre(s, LEERLO + 0.8, LEERLO + 1.2, LEERLO + 1.8)} /></g>
      {/* parlante y oreja (escuchar) */}
      <g transform={`translate(250 790) scale(${pop(HACE + 0.3) * vibra})`}>
        <rect x={-96} y={-140} width={192} height={280} rx={26} fill="#2E2E3A" stroke="#14141C" strokeWidth={6} />
        <circle cx={0} cy={-52} r={42} fill="#4A4A5C" stroke="#14141C" strokeWidth={4} /><circle cx={0} cy={-52} r={16} fill="#1A1A22" />
        <circle cx={0} cy={50} r={62} fill="#4A4A5C" stroke="#14141C" strokeWidth={4} /><circle cx={0} cy={50} r={26} fill="#1A1A22" />
      </g>
      <g transform={`translate(790 770) scale(${pop(NADIE)})`}>
        <path d="M -10 -120 C 90 -150 140 -40 100 50 C 80 100 30 100 10 140 C -20 170 -70 130 -60 90 C -90 50 -100 -90 -10 -120 Z" fill="#E9B590" stroke="#8A5A40" strokeWidth={6} />
        <path d="M 0 -80 C 70 -90 90 -20 60 30 C 40 60 10 40 20 10" stroke="#B9805E" strokeWidth={10} fill="none" strokeLinecap="round" />
      </g>
      {[0, 1, 2].map((i) => <path key={i} d={`M ${350 + i * 40} ${730 - i * 12} Q ${380 + i * 40} 790 ${350 + i * 40} ${850 + i * 12}`} stroke={LIMA} strokeWidth={8} fill="none" strokeLinecap="round" opacity={abre(s, ESCUCH + 0.0 + i * 0.12, ESCUCH + 0.35 + i * 0.12, ESCUCH + 0.8 + i * 0.12)} />)}
      <Recorrido puntos={rutaOjo} t0={LEERLO} t1={LEERLO + 0.95} render={(x, y, a) => <Nube x={x} y={y} sc={0.7} boca={0.9} ang={a * 0.1} />} />
